import React, { useState } from 'react';

interface Permission {
  id: number;
  name: string;
  description: string;
  enabled?: boolean;
}

const PermissionSystem = () => {
  const [permissions, setPermissions] = useState<Permission[]>([
    { id: 1, name: 'Read', description: 'Can view content' },
    { id: 2, name: 'Write', description: 'Can create content' },
    { id: 3, name: 'Delete', description: 'Can remove content' }
  ]);

  const togglePermission = (id: number) => {
    setPermissions(prev => prev.map(perm => 
      perm.id === id ? { ...perm, enabled: !perm.enabled } : perm
    ));
  };

  return (
    <div>
      <h1>Permission System</h1>
      {permissions.map(permission => (
        <div key={permission.id}>
          <h3>{permission.name}</h3>
          <p>{permission.description}</p>
          <button onClick={() => togglePermission(permission.id)}>
            Toggle
          </button>
          {/* Add status paragraph here */}
        </div>
      ))}
    </div>
  );
};
